<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administracion | TerraMedicion</title><style>:root{--navy:#102a3b;--mint:#36c69b;--paper:#f4f7f8;--line:#e2e9eb;--text:#193441;--muted:#70838a}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--text);font:15px Inter,Segoe UI,Arial,sans-serif}.sidebar{position:fixed;inset:0 auto 0 0;width:270px;padding:20px 14px;background:#fff;color:var(--text);border-right:1px solid var(--line);display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;padding:13px 12px 30px;font-weight:800;font-size:17px;letter-spacing:.3px}.brand:before{content:'T';display:grid;place-items:center;width:31px;height:31px;border-radius:9px;color:#fff;background:var(--navy);font-size:15px}.brand span{color:#159670}.menu-label{font-size:10px;color:#98a8ad;letter-spacing:1.2px;font-weight:800;padding:0 12px 9px;text-transform:uppercase}.nav-link{position:relative;display:flex;align-items:center;gap:12px;color:#63777f;padding:11px 12px;margin:4px 0;border-radius:9px;font-weight:600;transition:background .16s,color .16s}.nav-link:hover{color:var(--navy);background:#f3f8f7}.nav-link.active{color:#0c705a;background:#e7f7f1}.nav-link.active:after{content:'';position:absolute;right:-14px;top:11px;bottom:11px;width:3px;border-radius:4px 0 0 4px;background:var(--mint)}.nav-link b{display:grid;place-items:center;width:18px;color:#7d959b;font-size:17px}.nav-link.active b{color:#0d956f}.sidebar-footer{margin-top:auto;padding:17px 12px 3px;border-top:1px solid var(--line)}.profile-mini{display:flex;gap:9px;align-items:center;margin-bottom:12px;font-size:12px;color:var(--muted)}.profile-avatar{display:grid;place-items:center;width:28px;height:28px;background:#e7f7f1;color:#0d956f;border-radius:50%;font-weight:800}.logout{width:100%;text-align:left;font:inherit;font-size:13px;color:#7b8d93;cursor:pointer;background:transparent;border:0;padding:8px 0}.logout:hover{color:#ba3b3b}.main{margin-left:270px;min-height:100vh;padding:38px clamp(22px,4vw,62px);max-width:1540px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:31px}.topbar p{margin:5px 0 0;color:var(--muted)}.user{background:#fff;border:1px solid var(--line);border-radius:30px;padding:9px 14px;color:var(--muted);font-size:13px}h1{font-size:28px;margin:0;letter-spacing:-.6px}h2{font-size:17px;margin:0}.card{background:#fff;border:1px solid var(--line);border-radius:13px;padding:22px;box-shadow:0 5px 18px rgba(21,50,61,.035)}.btn{display:inline-flex;gap:7px;border:0;border-radius:8px;background:var(--mint);color:#062b2c;padding:11px 15px;font-weight:800;cursor:pointer;text-decoration:none}.input{display:block;width:100%;padding:11px 12px;background:#fff;border:1px solid #ccd9dc;border-radius:8px;margin:6px 0 16px;font:inherit}.notice{padding:14px 17px;margin-bottom:23px;border-radius:9px;background:#ddf8ef;color:#126449;border:1px solid #bcebd9}table{width:100%;border-collapse:collapse}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.7px}td,th{padding:14px 10px;text-align:left;border-bottom:1px solid var(--line)}tr:last-child td{border-bottom:0}.badge{display:inline-block;border-radius:99px;padding:5px 9px;font-size:11px;font-weight:800;background:#f1f4f5;color:#53666e}.badge.published{background:#dcf8ef;color:#087158}.badge.draft{background:#fff3d7;color:#8c6500}@media(max-width:760px){.sidebar{position:static;width:100%;padding:18px}.brand{padding-bottom:18px}.sidebar nav{display:flex;overflow:auto;gap:6px}.menu-label,.sidebar-footer{display:none}.nav-link{white-space:nowrap}.main{margin:0;padding:26px 18px}.user{display:none}}</style></head><body><aside class="sidebar"><a class="brand" href="{{route('admin.dashboard')}}">TERRA<span>MEDICION</span></a><div class="menu-label">Gestion de contenido</div><nav><a class="nav-link {{request()->routeIs('admin.dashboard')?'active':''}}" href